from taf.cloud.ncir.ncir_client import NcirClient


class NcirConnection(object):
    def __init__(self, address, version, **version_parameters):
        self._interface = NcirClient.create_connection(address, version, **version_parameters)

    def get_host_id_by_name(self, host_name):
        return self._interface.get_host_id_by_name(host_name)

    def lock_host(self, host_id):
        self._interface.lock_host(host_id)

    def unlock_host(self, host_id):
        self._interface.unlock_host(host_id)

    def force_lock_host(self, host_id):
        self._interface.force_lock_host(host_id)

    def swact_host(self, host_id):
        self._interface.swact_host(host_id)
